import React from 'react';
import { Card, CardContent, Typography, Grid, Stack, Chip } from '@mui/material';
import { Line, Bar } from 'react-chartjs-2';
import { Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, BarElement, Tooltip as ChartTooltip, Legend } from 'chart.js';

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, BarElement, ChartTooltip, Legend);

function AnalyticsCharts() {
  const lineData = {
    labels: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun'],
    datasets: [
      { label: 'Passes', data: [82, 85, 88, 90, 91, 92], borderColor: '#2563EB', backgroundColor: 'rgba(37,99,235,0.14)', tension: 0.35, fill: true },
      { label: 'Failures', data: [18, 15, 12, 10, 9, 8], borderColor: '#EF4444', backgroundColor: 'rgba(239,68,68,0.12)', tension: 0.35, fill: true },
    ],
  };

  const moduleData = {
    labels: ['Auth', 'Payments', 'Search', 'UI'],
    datasets: [{ label: 'Failure Count', data: [35, 24, 18, 16], backgroundColor: ['#2563EB', '#F59E0B', '#22C55E', '#EF4444'] }],
  };

  const flakyData = {
    labels: ['Checkout', 'Billing', 'Search', 'Login'],
    datasets: [{ label: 'Flake Rate', data: [83, 76, 61, 54], backgroundColor: ['#EF4444', '#F59E0B', '#2563EB', '#22C55E'] }],
  };

  return (
    <Grid container spacing={2.5}>
      <Grid item xs={12}>
        <Card>
          <CardContent>
            <Stack direction="row" justifyContent="space-between" alignItems="center" mb={2}>
              <Typography variant="h6">Pass vs Fail Trend</Typography>
              <Chip label="Weekly trend" color="primary" size="small" />
            </Stack>
            <Line data={lineData} options={{ responsive: true, maintainAspectRatio: false, plugins: { legend: { labels: { color: '#111827' } } }, scales: { x: { ticks: { color: '#6B7280' }, grid: { display: false } }, y: { ticks: { color: '#6B7280' }, grid: { color: '#E5E7EB' } } } }} />
          </CardContent>
        </Card>
      </Grid>
      <Grid item xs={12} md={6}>
        <Card>
          <CardContent>
            <Typography variant="h6" mb={2}>Top Failing Modules</Typography>
            <Bar data={moduleData} options={{ responsive: true, maintainAspectRatio: false, plugins: { legend: { display: false } }, scales: { x: { ticks: { color: '#6B7280' }, grid: { display: false } }, y: { ticks: { color: '#6B7280' }, grid: { color: '#E5E7EB' } } } }} />
          </CardContent>
        </Card>
      </Grid>
      <Grid item xs={12} md={6}>
        <Card>
          <CardContent>
            <Typography variant="h6" mb={2}>Flaky Tests Analysis</Typography>
            <Bar data={flakyData} options={{ responsive: true, maintainAspectRatio: false, plugins: { legend: { display: false } }, scales: { x: { ticks: { color: '#6B7280' }, grid: { display: false } }, y: { ticks: { color: '#6B7280' }, grid: { color: '#E5E7EB' } } } }} />
          </CardContent>
        </Card>
      </Grid>
    </Grid>
  );
}

export default AnalyticsCharts;
